def is_upper_bound(f, g, c, x0, xmax):
    for x in range(x0 + 1, xmax + 1):
        if not (c * g(x) >= f(x)):
            return False
    return True

def rank(label):
    order = ['1', 'logn', 'n', 'nlogn', 'n^2', '2^n']
    if label in order:
        return order.index(label)
    return -1
